content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body, html, #root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  background-color: #050508;
  color: #ffffff;
}

.app-container {
  position: relative;
  width: 100vw;
  height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  background: radial-gradient(circle at center, #1b1b2f 0%, #050508 100%);
}

.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.header-title {
  position: absolute;
  top: 20px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10;
  font-size: 1.8rem;
  font-weight: 700;
  letter-spacing: 2px;
  color: #e2e8f0;
  text-shadow: 0 0 10px rgba(255, 255, 255, 0.5);
  pointer-events: none;
}

.controls-hint {
  position: absolute;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10;
  background: rgba(15, 15, 25, 0.7);
  padding: 8px 16px;
  border-radius: 20px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  font-size: 0.9rem;
  color: #94a3b8;
  backdrop-filter: blur(5px);
  pointer-events: none;
  text-align: center;
}

.info-panel {
  position: absolute;
  top: 80px;
  right: 20px;
  width: 320px;
  max-height: calc(100vh - 120px);
  background: rgba(15, 15, 25, 0.85);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 12px;
  padding: 24px;
  z-index: 20;
  backdrop-filter: blur(10px);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  overflow-y: auto;
  animation: fadeIn 0.3s ease-out forwards;
}

.info-title {
  font-size: 1.5rem;
  font-weight: 600;
  margin-bottom: 12px;
  color: #f8fafc;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  padding-bottom: 8px;
}

.info-text {
  font-size: 0.95rem;
  line-height: 1.6;
  color: #cbd5e1;
  margin-bottom: 16px;
}

.close-btn {
  position: absolute;
  top: 16px;
  right: 16px;
  background: transparent;
  border: none;
  color: #94a3b8;
  font-size: 1.2rem;
  cursor: pointer;
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  transition: all 0.2s;
}

.close-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #ffffff;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 768px) {
  .header-title {
    font-size: 1.3rem;
    top: 10px;
  }

  .info-panel {
    top: auto;
    bottom: 0;
    right: 0;
    left: 0;
    width: 100%;
    max-height: 50vh;
    border-radius: 20px 20px 0 0;
    border-bottom: none;
  }

  .controls-hint {
    bottom: 70px;
    font-size: 0.8rem;
    padding: 6px 12px;
  }
}

export interface PlanetData {
  id: string;
  name: string;
  color: string;
  size: number;
  distance: number;
  speed: number;
  description: string;
}

export interface SolarSystemProps {
  selectedPlanet: PlanetData | null;
  onSelectPlanet: (planet: PlanetData | null) => void;
}

export interface PlanetInfoProps {
  planet: PlanetData | null;
  onClose: () => void;
}

