export default function SolarSystem({ selectedPlanet, onSelectPlanet }: SolarSystemProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const selectedPlanetRef = useRef<PlanetData | null>(selectedPlanet);

  // Keep ref updated for the animation loop
  useEffect(() => {
    selectedPlanetRef.current = selectedPlanet;
  }, [selectedPlanet]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // Scene setup
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x050508);

    // Camera setup
    const camera = new THREE.PerspectiveCamera(
      60,
      container.clientWidth / container.clientHeight,
      0.1,
      1000
    );
    camera.position.set(0, 25, 45);
    camera.lookAt(0, 0, 0);

    // Renderer setup
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(container.clientWidth, container.clientHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    container.appendChild(renderer.domElement);

    // Lights
    const ambientLight = new THREE.AmbientLight(0x333333);
    scene.add(ambientLight);

    const sunLight = new THREE.PointLight(0xffffff, 2, 300);
    sunLight.position.set(0, 0, 0);
    scene.add(sunLight);

    // Sun creation
    const sunGeometry = new THREE.SphereGeometry(3.5, 32, 32);
    const sunMaterial = new THREE.MeshBasicMaterial({ color: 0xffaa00 });
    const sunMesh = new THREE.Mesh(sunGeometry, sunMaterial);
    scene.add(sunMesh);

    // Planet meshes map
    const planetMeshes: { [key: string]: THREE.Mesh } = {};
    const planetAngles: { [key: string]: number } = {};

    PLANETS.forEach((planet) => {
      // Orbit line
      const orbitGeometry = new THREE.BufferGeometry();
      const points = [];
      for (let i = 0; i <= 64; i++) {
        const theta = (i / 64) * Math.PI * 2;
        points.push(new THREE.Vector3(Math.cos(theta) * planet.distance, 0, Math.sin(theta) * planet.distance));
      }
      orbitGeometry.setFromPoints(points);
      const orbitMaterial = new THREE.LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.1 });
      const orbitLine = new THREE.Line(orbitGeometry, orbitMaterial);
      scene.add(orbitLine);

      // Planet mesh
      const geometry = new THREE.SphereGeometry(planet.size, 32, 32);
      const material = new THREE.MeshStandardMaterial({
        color: planet.color,
        roughness: 0.8,
      });
      const mesh = new THREE.Mesh(geometry, material);
      mesh.userData = { planet };
      scene.add(mesh);

      planetMeshes[planet.id] = mesh;
      planetAngles[planet.id] = Math.random() * Math.PI * 2; // ランダムな初期位置
    });

    // Raycaster for interaction
    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();

    const handlePointerDown = (event: PointerEvent) => {
      const rect = renderer.domElement.getBoundingClientRect();
      mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
      mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;

      raycaster.setFromCamera(mouse, camera);
      const meshes = Object.values(planetMeshes);
      const intersects = raycaster.intersectObjects(meshes);

      if (intersects.length > 0) {
        const clickedMesh = intersects[0].object as THREE.Mesh;
        const planetData = clickedMesh.userData.planet as PlanetData;
        onSelectPlanet(planetData);
      } else {
        // 背景をクリックした場合は選択解除
        onSelectPlanet(null);
      }
    };

    renderer.domElement.addEventListener('pointerdown', handlePointerDown);

    // Window resize
    const handleResize = () => {
      if (!container) return;
      camera.aspect = container.clientWidth / container.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(container.clientWidth, container.clientHeight);
    };

    window.addEventListener('resize', handleResize);

    // Animation loop
    let animationFrameId: number;

    const animate = () => {
      animationFrameId = requestAnimationFrame(animate);

      // Sun rotation
      sunMesh.rotation.y += 0.002;

      // Planets orbit
      PLANETS.forEach((planet) => {
        const mesh = planetMeshes[planet.id];
        if (mesh) {
          planetAngles[planet.id] += planet.speed * 0.5;
          const angle = planetAngles[planet.id];
          mesh.position.x = Math.cos(angle) * planet.distance;
          mesh.position.z = Math.sin(angle) * planet.distance;
          mesh.rotation.y += 0.01;
        }
      });

      // Camera follow selected planet smoothly if any
      const currentSelected = selectedPlanetRef.current;
      if (currentSelected) {
        const targetMesh = planetMeshes[currentSelected.id];
        if (targetMesh) {
          const targetX = targetMesh.position.x;
          const targetZ = targetMesh.position.z;
          // カメラをターゲットの近くに寄せる
          camera.position.x += (targetX - camera.position.x) * 0.05;
          camera.position.z += ((targetZ + 5) - camera.position.z) * 0.05;
          camera.position.y += (3 - camera.position.y) * 0.05;
          camera.lookAt(targetX, 0, targetZ);
        }
      } else {
        // デフォルトビューへ戻る
        camera.position.x += (0 - camera.position.x) * 0.03;
        camera.position.z += (45 - camera.position.z) * 0.03;
        camera.position.y += (25 - camera.position.y) * 0.03;
        camera.lookAt(0, 0, 0);
      }

      renderer.render(scene, camera);
    };

    animate();

    return () => {
      window.removeEventListener('resize', handleResize);
      renderer.domElement.removeEventListener('pointerdown', handlePointerDown);
      cancelAnimationFrame(animationFrameId);
      if (container.contains(renderer.domElement)) {
        container.removeChild(renderer.domElement);
      }
      renderer.dispose();
    };
  }, [onSelectPlanet]);

  return <div className="canvas-container" ref={containerRef} />;
}

import { PlanetInfoProps } from '../types';

export default function PlanetInfo({ planet, onClose }: PlanetInfoProps) {
  if (!planet) return null;

  return (
    <div className="info-panel">
      <button className="close-btn" onClick={onClose} aria-label="閉じる">
        ✕
      </button>
      <h2 className="info-title">{planet.name}</h2>
      <p className="info-text">{planet.description}</p>
      <div style={{ fontSize: '0.85rem', color: '#94a3b8', borderTop: '1px solid rgba(255,255,255,0.1)', paddingTop: '10px' }}>
        <p><strong>太陽からの距離:</strong> 約 {planet.distance * 150} 万km (相対)</p>
        <p><strong>公転速度:</strong> 相対値 {planet.speed.toFixed(3)}</p>
      </div>
    </div>
  );
}

import { useState } from 'react';
import SolarSystem from './components/SolarSystem';
import PlanetInfo from './components/PlanetInfo';
import { PlanetData } from './types';
import './index.css';

export default function App() {
  const [selectedPlanet, setSelectedPlanet] = useState<PlanetData | null>(null);

  return (
    <div className="app-container">
      <h1 className="header-title">太陽系 3D シミュレーション</h1>

      <SolarSystem 
        selectedPlanet={selectedPlanet} 
        onSelectPlanet={setSelectedPlanet} 
      />

      <PlanetInfo 
        planet={selectedPlanet} 
        onClose={() => setSelectedPlanet(null)} 
      />

      <div className="controls-hint">
        惑星をクリックして詳細情報を表示 / 背景クリックで全体ビューに戻る
      </div>
    </div>
  );
}
